let adminAlliancePage='overview',adminAllianceSelected='',multihunterPage='overview';
function adminAllianceProfiles(){return [...new Map([state.alliance,...(state.allianceDirectory||[])].map(a=>[a.name,a])).values()];}
function selectedAdminAlliance(){const profiles=adminAllianceProfiles();return profiles.find(a=>a.name===adminAllianceSelected)||profiles[0];}
function adminSubpageNav(pages,current,attribute){return '<nav class="alliance-tabs admin-subpages">'+pages.map(([id,label])=>'<button class="'+(current===id?'active':'')+'" '+attribute+'="'+id+'">'+label+'</button>').join('')+'</nav>';}
function renderAdminAllianceCenter(){const el=document.getElementById('adminContent');if(!el)return;document.getElementById('adminPageHeading').textContent='Alliance Controlcenter';document.getElementById('adminPageDescription').textContent='Staff alliance administration, separated into dedicated control pages.';if(!window.isGameAdmin){el.innerHTML='<p class="notice">Game-admin access required.</p>';return;}const a=selectedAdminAlliance()||(adminAlliancePage==='keyholders'?{name:''}:null);if(!a){el.innerHTML='<p>No alliances available.</p>';return;}adminAllianceSelected=a.name;const nav=adminSubpageNav([['overview','Overview'],['settings','Settings'],['members','Members'],['ranks','Ranks'],['keyholders','Keyholders'],['funds','Funds'],['structures','Structures']],adminAlliancePage,'data-admin-alliance-page');let content='';
 if(adminAlliancePage==='overview')content='<section class="panel"><div class="ph"><div class="pt">ALLIANCE DIRECTORY · STAFF</div></div><div class="alliance-kpis"><div><small>ALLIANCE</small><b>'+esc(a.name)+'</b></div><div><small>MEMBERS</small><b>'+(a.members||[]).length+'</b></div><div><small>OWNERS</small><b>'+(a.members||[]).filter(m=>m.rank==='Owner').length+'</b></div></div><p class="note" style="margin:18px">Choose an alliance above, then open its dedicated settings, member, rank, fund or structure editor. Personal Owner passkeys remain visible only to their own holders.</p></section>';
 if(adminAlliancePage==='settings')content='<div class="alliance-settings-grid">'+[['name','Alliance name'],['description','Description'],['recruitmentMessage','Recruitment message'],['motd','MOTD']].map(([key,label])=>'<section class="panel"><div class="ph"><div class="pt">'+label+'</div></div><div class="settings-body"><label class="field" for="staffAlly-'+key+'">'+label+'</label>'+(key==='name'?'<input id="staffAlly-'+key+'" maxlength="40" value="'+esc(a[key]||'')+'">':'<textarea id="staffAlly-'+key+'" rows="5" maxlength="2000">'+esc(a[key]||'')+'</textarea>')+'<button class="btn primary" data-admin-alliance-setting="'+key+'">SAVE '+label.toUpperCase()+'</button></div></section>').join('')+'</div>';
 if(adminAlliancePage==='members')content='<section class="panel"><div class="ph"><div class="pt">MEMBER ASSIGNMENT & DUMMY PLANETS</div></div><div class="controls"><label class="field" for="adminAlliancePlanet">Planet<select id="adminAlliancePlanet">'+state.galaxy.map(p=>'<option value="'+p.id+'" '+(p.id===state.adminSelected?'selected':'')+'>'+esc(p.name)+' · '+esc(p.alliance||'Unaffiliated')+'</option>').join('')+'</select></label><label class="field" for="admAlliance">Assign alliance<select id="admAlliance">'+allianceChoices().map(n=>'<option '+(n===a.name?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label><button class="btn primary" data-admin-alliance-assign>APPLY MEMBERSHIP</button><button class="btn" data-admin-alliance-dummy>CREATE DUMMY MEMBER</button></div></section><section class="panel"><div class="ph"><div class="pt">MEMBERS & OWNER RANKS</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Planet / member</th><th>Coordinates</th><th>Rank</th><th></th></tr></thead><tbody>'+(a.members||[]).map((m,i)=>'<tr><td>'+esc(m.planet)+'<small>'+esc(m.name)+'</small></td><td>'+esc(m.coords)+'</td><td><select id="staffMemberRank-'+i+'">'+ALLIANCE_RANKS.map(rank=>'<option '+(m.rank===rank?'selected':'')+'>'+rank+'</option>').join('')+'</select></td><td><button class="btn" data-admin-alliance-member="'+i+'">SAVE RANK</button></td></tr>').join('')+'</tbody></table></div></section>';
 if(adminAlliancePage==='ranks'){const defaults=defaultAlliancePermissions();content='<section class="panel"><div class="ph"><div class="pt">ALLIANCE RANK PERMISSIONS</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Permission</th>'+ALLIANCE_RANKS.map(r=>'<th>'+r+'</th>').join('')+'</tr></thead><tbody>'+ALLIANCE_PERMISSIONS.map(([key,label])=>'<tr><td>'+label+'</td>'+ALLIANCE_RANKS.map(rank=>'<td><input type="checkbox" data-staff-ally-permission="'+key+'" data-staff-ally-rank="'+rank+'" aria-label="'+rank+' · '+label+'" '+((a.rankPermissions?.[rank]?.[key]??defaults[rank][key])?'checked':'')+'></td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-admin-alliance-save="ranks">SAVE RANK PERMISSIONS</button></div><p class="note" style="margin:16px">Owner grants are restricted to Owners and staff independently of this matrix.</p></section>';}
 if(adminAlliancePage==='keyholders')content='<section class="panel"><div class="ph"><div class="pt">OWNER KEYHOLDERS</div><span class="meta">STAFF AUDIT · KEYS REMAIN PRIVATE</span></div><div class="settings-body"><p>All alliances, including archived key registrations. Secrets remain hidden unless the holder authorises disclosure with their passphrase.</p><div id="staffKeyholdersContent">Loading keyholders…</div><button class="btn" data-admin-alliance-page="members">MANAGE OWNER RANKS →</button></div></section>';if(adminAlliancePage==='funds')content='<section class="panel"><div class="ph"><div class="pt">RESOURCE RESERVES & MINIMUMS</div></div><div class="admin-form">'+['metal','crystal','eonium'].map(k=>'<label class="field">'+RES[k].label+' reserve<input id="staffFund-'+k+'" type="number" min="0" value="'+(a.fund?.[k]||0)+'"></label><label class="field">'+RES[k].label+' minimum<input id="staffMinimum-'+k+'" type="number" min="0" value="'+(a.fundMinimum?.[k]||0)+'"></label>').join('')+'<label class="field">Tax (0–5%)<input id="staffAllianceTax" type="number" min="0" max="5" value="'+(a.tax||0)+'"></label></div><div class="controls"><button class="btn primary" data-admin-alliance-save="funds">SAVE RESERVES & TAX</button></div></section>';
 if(adminAlliancePage==='structures')content='<section class="panel"><div class="ph"><div class="pt">STRONGHOLD & STRUCTURE STATE</div></div><div class="settings-body"><label class="field" for="staffAllianceFortress">Fortress configuration</label><textarea id="staffAllianceFortress" rows="6" spellcheck="false">'+esc(JSON.stringify(a.fortress||{},null,2))+'</textarea><label class="field" for="staffAllianceStructures">Active structures, build queue and cooldowns</label><textarea id="staffAllianceStructures" rows="14" spellcheck="false">'+esc(JSON.stringify(a.structures||{active:[],buildQueue:[],cooldowns:{}},null,2))+'</textarea><button class="btn primary" data-admin-alliance-save="structures">SAVE STRUCTURE STATE</button><p>Advanced staff editor. Structure planets must retain valid reserved slots 11–15; the Planet Editor manages their underlying planet records.</p></div></section>';
 el.innerHTML=(adminAlliancePage==='keyholders'?'<div class="controls"><span class="tag gold">ALL ALLIANCES · STAFF ONLY</span></div>':'<div class="controls"><label class="field" for="staffAllianceSelect">Selected alliance<select id="staffAllianceSelect">'+adminAllianceProfiles().map(p=>'<option '+(p.name===a.name?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><span class="tag gold">STAFF ONLY</span></div>')+nav+'<div class="admin-alliance-subpage">'+content+'</div>';if(adminAlliancePage==='keyholders')loadStaffKeyholders();}
async function refreshAdminAlliances(){applySharedDirectory(await centralDirectoryRequest('/api/planets'));renderAdminAllianceCenter();}
async function saveAdminAllianceSetting(key){if(!window.isGameAdmin)return;const a=selectedAdminAlliance(),value=document.getElementById('staffAlly-'+key).value;await syncPlanetDirectory();const result=await centralDirectoryRequest('/api/alliance-control/settings?alliance='+encodeURIComponent(a.name),{[key]:value,revision:planetDirectoryRevision});adminAllianceSelected=result.name||a.name;await refreshAdminAlliances();notify('Alliance setting saved.');}
async function saveAdminAllianceEditor(kind){if(!window.isGameAdmin)return;const a=selectedAdminAlliance(),before=copy(a);try{if(kind==='ranks'){a.rankPermissions=defaultAlliancePermissions();document.querySelectorAll('[data-staff-ally-permission]').forEach(input=>a.rankPermissions[input.dataset.staffAllyRank][input.dataset.staffAllyPermission]=input.checked);}if(kind==='funds'){for(const [key,prefix] of [['fund','staffFund-'],['fundMinimum','staffMinimum-']]){a[key]=a[key]||{};for(const r of ['metal','crystal','eonium']){const n=Number(document.getElementById(prefix+r).value);if(!Number.isSafeInteger(n)||n<0)throw Error('Use non-negative whole resource amounts.');a[key][r]=n;}}const tax=Number(document.getElementById('staffAllianceTax').value);if(!Number.isFinite(tax)||tax<0||tax>5)throw Error('Tax must be between 0 and 5%.');a.tax=tax;}if(kind==='structures'){const fortress=JSON.parse(document.getElementById('staffAllianceFortress').value),structures=JSON.parse(document.getElementById('staffAllianceStructures').value);if(!fortress||typeof fortress!=='object'||Array.isArray(fortress)||!structures||!Array.isArray(structures.active||[])||!Array.isArray(structures.buildQueue||[]))throw Error('Use valid fortress and structure objects.');a.fortress=fortress;a.structures=structures;}const result=await centralDirectoryRequest('/api/planets',{revision:planetDirectoryRevision,...directorySnapshot()});planetDirectoryRevision=result.revision;await refreshAdminAlliances();notify('Alliance editor saved.');}catch(error){Object.assign(a,before);throw error;}}
function renderMultihunters(){const el=document.getElementById('adminContent');document.getElementById('adminPageHeading').textContent='Multihunters';document.getElementById('adminPageDescription').textContent='Reserved staff workspace for future investigations and case management.';if(!window.isGameAdmin){el.innerHTML='<p>Game-admin access required.</p>';return;}if(multihunterPage==='farming'){renderFleetFarmingTool(el);return;}const labels={overview:'Overview',cases:'Case queue',reports:'Reports',tools:'Tools',farming:'Fleet farming analysis',logs:'Raw access log',multi:'Multi'};if(['logs','multi'].includes(multihunterPage)){el.innerHTML=adminSubpageNav(Object.entries(labels),multihunterPage,'data-multihunter-page')+'<section class="panel"><div class="ph"><div class="pt">'+labels[multihunterPage].toUpperCase()+'</div><span class="tag gold">STAFF ONLY</span></div><div id="multihunterData" class="settings-body">Loading account access data…</div></section>';loadMultihunterData(multihunterPage);return;}el.innerHTML=adminSubpageNav(Object.entries(labels),multihunterPage,'data-multihunter-page')+'<section class="panel"><div class="ph"><div class="pt">'+labels[multihunterPage].toUpperCase()+'</div><span class="tag gold">PLACEHOLDER</span></div><div class="settings-body"><h3>Investigation control workspace</h3><p>This subpage is reserved for a future staff workflow. No investigations, tracking, bans or account actions are enabled here.</p></div></section>';}
document.addEventListener('change',e=>{if(e.target.id==='staffAllianceSelect'){adminAllianceSelected=e.target.value;renderAdminAllianceCenter();}});
document.addEventListener('click',async e=>{try{const tab=e.target.closest('[data-admin-alliance-page]');if(tab){adminAlliancePage=tab.dataset.adminAlliancePage;renderAdminAllianceCenter();}const mh=e.target.closest('[data-multihunter-page]');if(mh){multihunterPage=mh.dataset.multihunterPage;renderMultihunters();}const setting=e.target.closest('[data-admin-alliance-setting]');if(setting)await saveAdminAllianceSetting(setting.dataset.adminAllianceSetting);const editor=e.target.closest('[data-admin-alliance-save]');if(editor)await saveAdminAllianceEditor(editor.dataset.adminAllianceSave);if(e.target.closest('[data-admin-alliance-assign]')&&window.isGameAdmin){state.adminSelected=document.getElementById('adminAlliancePlanet').value;applyAdminPlanetModule('alliance');await syncPlanetDirectory();renderAdminAllianceCenter();}if(e.target.closest('[data-admin-alliance-dummy]')&&window.isGameAdmin){addAdminDummyMember(selectedAdminAlliance().name);renderAdminAllianceCenter();}const member=e.target.closest('[data-admin-alliance-member]');if(member&&window.isGameAdmin){const a=selectedAdminAlliance(),m=a.members[Number(member.dataset.adminAllianceMember)];await syncPlanetDirectory();await centralDirectoryRequest('/api/alliance-control/members?alliance='+encodeURIComponent(a.name),{memberId:m.id,planetId:m.planetId,rank:document.getElementById('staffMemberRank-'+member.dataset.adminAllianceMember).value,revision:planetDirectoryRevision});await refreshAdminAlliances();notify('Member rank saved.');}}catch(error){notify(error.message,true);}});

async function loadStaffKeyholders(){try{const data=await centralDirectoryRequest('/api/alliance-control/keyholders');const el=document.getElementById('staffKeyholdersContent');if(!el||adminAlliancePage!=='keyholders')return;el.innerHTML=data.keyholders.length?'<div class="table-wrap"><table class="table"><thead><tr><th>Alliance</th><th>Keyholder</th><th>Status</th><th>Issued</th><th>Authorised reveal</th></tr></thead><tbody>'+data.keyholders.map(k=>{const key=k.allianceId+'-'+k.ownerId;return '<tr><td>'+esc(k.alliance)+'</td><td>'+esc(k.username)+'</td><td>'+esc(k.status)+'</td><td>'+new Date(k.createdAt).toLocaleString()+'</td><td>'+(k.canDisclose&&k.status==='Active'?'<input type="password" autocomplete="off" id="staffReveal-'+esc(key)+'" placeholder="Holder-provided passphrase"><button class="btn" data-reveal-key-owner="'+esc(k.ownerId)+'" data-reveal-alliance="'+esc(k.allianceId)+'">REVEAL SECRET</button><input readonly type="text" data-staff-key-secret="'+esc(key)+'" placeholder="Secret hidden">':'Holder has not enabled admin reveal')+'</td></tr>';}).join('')+'</tbody></table></div>':'<p>No personal Owner keys have been issued yet.</p>';}catch(error){const el=document.getElementById('staffKeyholdersContent');if(el)el.textContent=error.message;}}

document.addEventListener('click',async e=>{const button=e.target.closest('[data-reveal-key-owner]');if(!button)return;const ownerId=button.dataset.revealKeyOwner,allianceId=button.dataset.revealAlliance,key=allianceId+'-'+ownerId,input=document.getElementById('staffReveal-'+key);try{const result=await centralDirectoryRequest('/api/alliance-control/reveal',{allianceId,ownerId,passphrase:input.value,revision:planetDirectoryRevision});input.value='';const field=document.querySelector('[data-staff-key-secret="'+key+'"]');if(field){field.value=result.secret;setTimeout(()=>{field.value='';},60000);}notify('Secret revealed temporarily with the holder’s passphrase.');}catch(error){notify(error.message,true);}});

let multiLogOffset=0;
async function loadMultihunterData(page){try{const data=await centralDirectoryRequest('/api/admin/access-logs?offset='+multiLogOffset),el=document.getElementById('multihunterData');if(!el||multihunterPage!==page)return;const date=t=>new Date(t).toLocaleString();if(page==='multi'){el.innerHTML='<p>Accounts linked by a shared observed edge IP. Shared IPs indicate a network connection, not proof of common account ownership.</p>'+data.shared.map(group=>'<article class="fleet-member-box"><h3>'+esc(group.ip)+' · '+group.accounts.length+' accounts</h3><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>First observed</th><th>Last observed</th></tr></thead><tbody>'+group.accounts.map(user=>'<tr><td>'+esc(user.username)+'</td><td>'+date(user.first_seen)+'</td><td>'+date(user.last_seen)+'</td></tr>').join('')+'</tbody></table></div></article>').join('')+(data.shared.length?'':'<p>No multiple accounts share an observed IP in the retained history.</p>');}else{el.innerHTML='<p>Raw signed-in page/API access metadata · '+data.retentionDays+' days. Request bodies, cookies, query values, passwords and keys are excluded. Missing edge IP is shown as unavailable.</p><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Account</th><th>IP</th><th>Method / path</th><th>Status</th></tr></thead><tbody>'+data.logs.map(row=>'<tr><td>'+date(row.created_at)+'</td><td>'+esc(row.username)+'</td><td>'+esc(row.ip||'Unavailable')+'</td><td>'+esc(row.method)+' '+esc(row.path)+'</td><td>'+row.status+'</td></tr>').join('')+'</tbody></table></div><div class="controls">'+(multiLogOffset?'<button class="btn" data-multi-log-page="'+Math.max(0,multiLogOffset-50)+'">NEWER</button>':'')+(data.hasMore?'<button class="btn" data-multi-log-page="'+data.nextOffset+'">OLDER</button>':'')+'</div><h3>Account IP history</h3><div class="table-wrap"><table class="table"><thead><tr><th>Account</th><th>IP</th><th>First observed</th><th>Last observed</th><th>Requests</th></tr></thead><tbody>'+data.history.map(row=>'<tr><td>'+esc(row.username)+'</td><td>'+esc(row.ip)+'</td><td>'+date(row.first_seen)+'</td><td>'+date(row.last_seen)+'</td><td>'+row.hits+'</td></tr>').join('')+'</tbody></table></div>';}}catch(error){const el=document.getElementById('multihunterData');if(el)el.textContent=error.message;}}
document.addEventListener('click',e=>{const page=e.target.closest('[data-multi-log-page]');if(page){multiLogOffset=Number(page.dataset.multiLogPage);loadMultihunterData('logs');}});
function renderFleetFarmingTool(el){const labels={overview:'Overview',cases:'Case queue',reports:'Reports',tools:'Tools',farming:'Fleet farming analysis',logs:'Raw access log',multi:'Multi'};el.innerHTML=adminSubpageNav(Object.entries(labels),'farming','data-multihunter-page')+'<section class="panel"><div class="ph"><div class="pt">FLEET FARMING ANALYSIS</div><span class="tag gold">STAFF REVIEW</span></div><div class="settings-body"><p>Review movements between two planets in either direction. Evidence supports human review; no automatic sanctions.</p><div class="settings-grid"><label>Planet A<select id="farmingPlanetA"></select></label><label>Planet B<select id="farmingPlanetB"></select></label><label>From tick<input id="farmingFrom" type="number" min="0" value="0"></label><label>Through tick<input id="farmingTo" type="number" min="0" value="1000000000"></label></div><button class="btn" data-farming-analyze disabled>ANALYZE PAIR</button><div id="farmingReport" aria-live="polite">Loading available planets…</div></div></section>';loadFarmingPlanets();}
async function loadFarmingPlanets(){try{const data=await centralDirectoryRequest('/api/fleet-movements');if(multihunterPage!=='farming')return;const options=data.planets.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.coords+' · '+p.name)+'</option>').join('');document.getElementById('farmingPlanetA').innerHTML=options;document.getElementById('farmingPlanetB').innerHTML=options;document.getElementById('farmingPlanetB').selectedIndex=data.planets.length>1?1:0;document.querySelector('[data-farming-analyze]').disabled=data.planets.length<2;document.getElementById('farmingReport').textContent='Select a pair. Only movements recorded since this feature was enabled are available.';}catch(error){const el=document.getElementById('farmingReport');if(el)el.textContent=error.message;}}
async function analyzeFarmingPair(){const el=document.getElementById('farmingReport');el.textContent='Analyzing recorded movements…';try{const query=new URLSearchParams({a:document.getElementById('farmingPlanetA').value,b:document.getElementById('farmingPlanetB').value,from:document.getElementById('farmingFrom').value,to:document.getElementById('farmingTo').value}),data=await centralDirectoryRequest('/api/fleet-movements?'+query);if(multihunterPage!=='farming')return;const name=id=>{const p=data.planets.find(p=>p.id===id);return p?p.coords+' · '+p.name:id;};el.innerHTML='<article class="fleet-member-box"><h3>'+esc(data.assessment)+'</h3><p>'+esc(data.limitations)+'</p><div class="settings-grid"><div class="panel">Reported attacks: <b>'+data.attacks+'</b></div><div class="panel">Completed reports: <b>'+data.completed+'</b></div><div class="panel">Asteroids captured: <b>'+nfmt(data.totalCaptured)+'</b></div></div>'+data.reasons.map(reason=>'<p>◈ '+esc(reason)+'</p>').join('')+(data.truncated?'<p>Limited to the first 1,000 movements. Narrow the tick range before drawing conclusions.</p>':'')+'</article><div class="table-wrap"><table class="table"><thead><tr><th>Origin → target</th><th>Mission</th><th>Launch / result tick</th><th>Ships sent</th><th>Attacker / defender losses</th><th>Captured asteroids</th></tr></thead><tbody>'+data.rows.map(r=>'<tr><td>'+esc(name(r.origin_id)+' → '+name(r.target_id))+'</td><td>'+esc(r.mission)+'</td><td>'+r.launch_tick+' / '+(r.result_tick??'Unknown')+'</td><td>'+nfmt(r.ships)+'</td><td>'+(r.attacker_lost??'Unknown')+' / '+(r.defender_lost??'Unknown')+'</td><td>'+(r.captured??'Unknown')+'</td></tr>').join('')+'</tbody></table></div>'+(data.rows.length?'':'<p>No recorded movements for this pair and tick range.</p>');}catch(error){el.textContent=error.message;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-farming-analyze]')&&window.isGameAdmin)analyzeFarmingPair();});
